function kindLabel(kind: CareKind, t: Translator) { return {daily:t('ชีวิตประจำวัน','Daily life'),symptom:t('อาการที่สังเกต','Symptoms'),visit:t('ไปหาคุณหมอ','Vet visit'),followup:t('ติดตามอาการ','Follow-up')}[kind]; }
function episodeLabel(status: CareEpisodeStatus, t: Translator) { return {ongoing:t('กำลังดูแล','Ongoing'),improving:t('ดีขึ้น','Improving'),resolved:t('ปิดเรื่องแล้ว','Resolved')}[status]; }
function moneyLabel(minor: number, currency: 'THB' | 'USD', locale: 'th' | 'en') { return new Intl.NumberFormat(locale === 'th' ? 'th-TH' : 'en-GB',{style:'currency',currency}).format(minor / 100); }
function reportDate(value: string, locale: 'th' | 'en') { return new Date(value).toLocaleString(locale === 'en' ? 'en-GB' : 'th-TH',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Bangkok'}); }
function section(icon: ReactNode, title: string, body: ReactNode, open = false) { return <details className="care-option" open={open || undefined}><summary>{icon}<span>{title}</span><ChevronDown size={18}/></summary><div className="care-option-body">{body}</div></details>; }
function openPhotoPicker(event:KeyboardEvent<HTMLLabelElement>){if(event.key==='Enter'||event.key===' '){event.preventDefault();event.currentTarget.querySelector('input')?.click();}}
async function demoPhoto(file: File): Promise<string> {
  if (!file.type.startsWith('image/') || file.size > 8 * 1024 * 1024) throw new Error('INVALID_IMAGE');
  const bitmap = await createImageBitmap(file);
  try {
    const canvas = document.createElement('canvas'), scale = Math.min(1,1000/Math.max(bitmap.width,bitmap.height));
    canvas.width=Math.max(1,Math.round(bitmap.width*scale)); canvas.height=Math.max(1,Math.round(bitmap.height*scale));
    const context = canvas.getContext('2d'); if (!context) throw new Error('INVALID_IMAGE');
    context.drawImage(bitmap,0,0,canvas.width,canvas.height);
    return canvas.toDataURL('image/jpeg',.8);
  } finally { bitmap.close(); }
}

